import type { DailyBrief, HNStory, GHNotification } from '../types/brief.js';

const MAX_SUMMARY_LENGTH = 280;

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function truncateSummary(summary: string): string {
  if (summary.length <= MAX_SUMMARY_LENGTH) {
    return summary;
  }
  const truncated = summary.slice(0, MAX_SUMMARY_LENGTH);
  const lastSpace = truncated.lastIndexOf(' ');
  if (lastSpace === -1) {
    return truncated + '…';
  }
  return truncated.slice(0, lastSpace) + '…';
}

export function renderToHtml(brief: DailyBrief): string {
  const weatherSection = brief.weather
    ? `<div class="weather-line">${brief.weather.lat}°, ${brief.weather.lon}°: <span class="data-val">${brief.weather.tempC}°C</span>, feels like <span class="data-val">${brief.weather.feelsLikeC ?? 'N/A'}°C</span> | ${escapeHtml(brief.weather.description)}</div><div class="weather-line">Humidity: <span class="data-val">${brief.weather.humidity ?? 'N/A'}%</span> | Wind: <span class="data-val">${brief.weather.windSpeedKmh} km/h</span></div>`
    : '<p class="unavailable">⚠ Unavailable</p>';

  const storiesHtml = brief.hnStories.length > 0
    ? brief.hnStories
        .map(
          (story: HNStory, i: number) =>
            `<li><span class="story-rank">${i + 1}.</span> <a href="${escapeHtml(story.url ?? '#')}">${escapeHtml(story.title)}</a> <span class="meta">(${escapeHtml(story.author)} — <span class="data-val">${story.points}</span> pts)</span></li>`
        )
        .join('')
    : '<p class="unavailable">⚠ Unavailable</p>';

  const ghHtml = brief.ghNotifications.length > 0
    ? brief.ghNotifications
        .map(
          (n: GHNotification) =>
            `<li><span class="gh-type">[${escapeHtml(n.type)}]</span> <span class="gh-repo">${escapeHtml(n.repo)}</span> — ${escapeHtml(n.title)} — <a href="${escapeHtml(n.humanUrl)}">${escapeHtml(n.humanUrl)}</a></li>`
        )
        .join('')
    : '<p class="unavailable">⚠ Unavailable</p>';

  let wikiHtml: string;
  if (brief.wikiArticle) {
    const thumbImg = brief.wikiArticle.thumbnailUrl
      ? `<img src="${escapeHtml(brief.wikiArticle.thumbnailUrl)}" alt="${escapeHtml(brief.wikiArticle.title)}" class="wiki-thumb">`
      : '';
    const truncatedSummary = truncateSummary(brief.wikiArticle.summary);
    wikiHtml = `<h3><a href="${escapeHtml(brief.wikiArticle.url)}">${escapeHtml(brief.wikiArticle.title)}</a></h3>${thumbImg}<p>${escapeHtml(truncatedSummary)}</p>`;
  } else {
    wikiHtml = '<p class="unavailable">⚠ Unavailable</p>';
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Daily Brief — ${escapeHtml(brief.generatedAt)}</title>
  <style>
    :root {
      --bg: #0d1117;
      --surface: #161b22;
      --surface-code: #1c2128;
      --border: #30363d;
      --border-subtle: #21262d;
      --text: #e6edf3;
      --text-muted: #8b949e;
      --accent: #f0883e;
      --link: #58a6ff;
      --success: #3fb950;
      --warning: #d29922;
      --error: #f85149;
    }

    @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Source+Serif+4:ital,wght@0,400;0,600;1,400&family=JetBrains+Mono:wght@400;500&display=swap');

    body {
      background: #0d1117;
      color: var(--text);
      font-family: 'Source Serif 4', Georgia, serif;
      max-width: 660px;
      margin: 0 auto;
      padding: 2rem;
      line-height: 1.65;
    }

    h1 {
      font-family: 'Playfair Display', serif;
      font-size: 2rem;
      font-weight: 700;
      color: var(--link);
      margin-top: 0;
      margin-bottom: 0.5rem;
      line-height: 1.2;
    }

    h2 {
      font-family: 'Source Serif 4', Georgia, serif;
      font-size: 1.125rem;
      font-weight: 600;
      color: var(--accent);
      margin-top: 0;
      margin-bottom: 0.75rem;
      line-height: 1.2;
    }

    h3 {
      font-family: 'Source Serif 4', Georgia, serif;
      font-size: 1rem;
      font-weight: 600;
      margin-top: 0;
      margin-bottom: 0.5rem;
      line-height: 1.2;
    }

    h3 a {
      color: var(--link);
      text-decoration: none;
    }

    .section {
      background: var(--surface);
      border: 1px solid var(--border);
      border-left: 3px solid var(--accent);
      border-radius: 6px;
      padding: 1.25rem;
      margin: 1rem 0;
    }

    .section h2 {
      margin-top: 0;
      margin-bottom: 0.75rem;
    }

    a {
      color: var(--link);
      text-decoration: none;
    }

    .unavailable {
      color: var(--warning);
      font-style: italic;
    }

    time {
      font-family: 'JetBrains Mono', monospace;
      font-size: 0.8125rem;
      color: var(--text-muted);
    }

    .masthead {
      border-bottom: 1px solid var(--border);
      padding-bottom: 1rem;
      margin-bottom: 1.5rem;
    }

    .weather-line {
      margin: 0.5rem 0;
    }

    .data-val {
      font-family: 'JetBrains Mono', monospace;
      font-size: 0.875rem;
      color: var(--text);
      background: var(--surface-code);
      padding: 1px 5px;
      border-radius: 3px;
    }

    .meta {
      font-family: 'JetBrains Mono', monospace;
      font-size: 0.8125rem;
      color: var(--text-muted);
    }

    .story-list {
      list-style: none;
      padding: 0;
    }

    .story-list li {
      padding: 0.375rem 0;
      border-bottom: 1px solid var(--border-subtle);
    }

    .story-list .story-rank {
      font-family: 'JetBrains Mono', monospace;
      color: var(--text-muted);
      display: inline-block;
      width: 1.5rem;
    }

    .gh-list {
      list-style: none;
      padding: 0;
    }

    .gh-list li {
      padding: 0.375rem 0;
      border-bottom: 1px solid var(--border-subtle);
    }

    .gh-type {
      font-family: 'JetBrains Mono', monospace;
      background: var(--surface-code);
      color: var(--text-muted);
      padding: 1px 4px;
      border-radius: 3px;
      font-size: 0.75rem;
    }

    .gh-repo {
      color: var(--success);
    }

    .wiki-block {
      overflow: hidden;
    }

    .wiki-thumb {
      float: right;
      margin: 0 0 0.5rem 1rem;
      max-width: 120px;
      border-radius: 4px;
      border: 1px solid var(--border);
    }

    .wiki-block p {
      font-style: italic;
      line-height: 1.7;
    }
  </style>
</head>
<body>
  <div class="masthead">
    <h1>📰 Daily Brief</h1>
    <time>${escapeHtml(brief.generatedAt)}</time>
  </div>

  <div class="section" id="weather">
    <h2>🌤 Weather</h2>
    ${weatherSection}
  </div>

  <div class="section" id="hn-stories">
    <h2>📰 Top HN Stories</h2>
    <ol class="story-list">${storiesHtml}</ol>
  </div>

  <div class="section" id="github">
    <h2>🔔 GitHub Notifications</h2>
    <ul class="gh-list">${ghHtml}</ul>
  </div>

  <div class="section" id="wikipedia">
    <h2>📖 Wikipedia</h2>
    <div class="wiki-block">${wikiHtml}</div>
  </div>
</body>
</html>`;
}

import { describe, it, expect } from 'vitest';
import { renderToHtml } from '../../src/renderers/html-renderer';
import type { DailyBrief } from '../../src/types/brief';

describe('renderers/html', () => {
  const fullBrief: DailyBrief = {
    generatedAt: new Date().toISOString(),
    weather: {
      lat: 51.5,
      lon: -0.1,
      tempC: 15,
      feelsLikeC: 13,
      humidity: 60,
      description: 'Clear sky',
      windSpeedKmh: 14,
      isDay: true,
    },
    hnStories: Array.from({ length: 10 }, (_, i) => ({
      id: `${i + 1}`,
      title: `Story ${i + 1}`,
      url: 'https://example.com',
      points: 100 - i * 10,
      commentCount: 42 - i,
      author: `user${i + 1}`,
    })),
    ghNotifications: [],
    wikiArticle: {
      title: 'Test Article',
      summary: 'This is a test.',
      url: 'https://en.wikipedia.org/wiki/Test',
      thumbnailUrl: null,
    },
    status: {
      weather: { ok: true },
      hn: { ok: true },
      github: { ok: true },
      wikipedia: { ok: true },
    },
  };

  const partialBrief: DailyBrief = {
    ...fullBrief,
    weather: null,
    status: {
      ...fullBrief.status,
      weather: { ok: false },
    },
  };

  it('returns valid HTML string', () => {
    const result = renderToHtml(fullBrief);
    expect(result.startsWith('<!DOCTYPE html>')).toBe(true);
  });

  it('null sections render unavailable notice', () => {
    const result = renderToHtml(partialBrief);
    expect(result).toContain('⚠ Unavailable');
  });

  it('escapes HTML in story titles', () => {
    const xssBrief: DailyBrief = {
      ...fullBrief,
      hnStories: [
        {
          id: '1',
          title: '<script>alert(1)</script>',
          url: 'https://example.com',
          points: 100,
          commentCount: 42,
          author: 'user',
        },
      ],
    };

    const result = renderToHtml(xssBrief);
    expect(result).toContain('&lt;script&gt;');
    expect(result).not.toContain('<script>');
  });

  it('renders all 10 HN stories', () => {
    const result = renderToHtml(fullBrief);
    expect(result).toContain('Story 10');
  });

  it('renders section even when null', () => {
    const emptyBrief: DailyBrief = {
      generatedAt: new Date().toISOString(),
      weather: null,
      hnStories: [],
      ghNotifications: [],
      wikiArticle: null,
      status: {
        weather: { ok: false },
        hn: { ok: false },
        github: { ok: false },
        wikipedia: { ok: false },
      },
    };

    const result = renderToHtml(emptyBrief);
    expect(result).toContain('id="weather"');
    expect(result).toContain('id="hn-stories"');
    expect(result).toContain('id="github"');
    expect(result).toContain('id="wikipedia"');
  });

  // Task 1.1 — Truncation bug (failing — renderer has bug)
  it('truncates Wikipedia summary at word boundary within 280 chars', () => {
    const longSummary = 'a '.repeat(150).trim(); // 299 chars
    const briefWithLongWiki: DailyBrief = {
      ...fullBrief,
      wikiArticle: {
        ...fullBrief.wikiArticle!,
        summary: longSummary,
      },
    };

    const result = renderToHtml(briefWithLongWiki);
    expect(result).toContain('…');
    expect(result).not.toContain(longSummary);
    const truncatedMatch = result.match(/<p>(.*?)<\/p>/);
    expect(truncatedMatch).not.toBeNull();
    const paragraph = truncatedMatch![1];
    expect(paragraph.endsWith('…')).toBe(true);
    expect(paragraph[paragraph.length - 2]).not.toBe(' ');
  });

  // Task 1.2 — Short summary preserved (passing)
  it('preserves Wikipedia summary under 280 chars without truncation', () => {
    const shortSummary = 'Short summary under limit.';
    const briefWithShortWiki: DailyBrief = {
      ...fullBrief,
      wikiArticle: {
        ...fullBrief.wikiArticle!,
        summary: shortSummary,
      },
    };

    const result = renderToHtml(briefWithShortWiki);
    expect(result).toContain(shortSummary);
    expect(result).not.toContain('…');
  });

  // Task 1.3 — Word-boundary edge case (failing — renderer has bug)
  it('truncates at last word boundary before 280 chars not mid-word', () => {
    const edgeSummary = 'a'.repeat(275) + ' boundary extra'; // 291 chars
    const briefWithEdgeWiki: DailyBrief = {
      ...fullBrief,
      wikiArticle: {
        ...fullBrief.wikiArticle!,
        summary: edgeSummary,
      },
    };

    const result = renderToHtml(briefWithEdgeWiki);
    expect(result).toContain('a'.repeat(275) + '…');
    expect(result).not.toContain('boundary');
  });

  // Task 1.4 — Dark mode color (passing)
  it('output contains dark mode background color #0d1117', () => {
    const result = renderToHtml(fullBrief);
    expect(/background:\s*#0d1117/.test(result)).toBe(true);
  });

  // Task 1.5 — XSS escaping on GitHub fields (passing)
  it('escapes HTML in GitHub notification fields', () => {
    const xssGhBrief: DailyBrief = {
      ...fullBrief,
      ghNotifications: [
        {
          id: '1',
          reason: 'review_requested',
          unread: true,
          title: '<b>title</b>',
          type: 'PullRequest',
          repo: '<script>repo</script>',
          repoUrl: 'https://github.com/repo',
          humanUrl: 'https://github.com/x?a=<evil>',
          updatedAt: new Date().toISOString(),
        },
      ],
    };

    const result = renderToHtml(xssGhBrief);
    expect(result).toContain('&lt;script&gt;');
    expect(result).toContain('&lt;b&gt;');
    expect(result).toContain('&lt;evil&gt;');
    expect(result).not.toContain('<script>');
    expect(result).not.toContain('<b>');
  });

  // Task 1.6 — GitHub notifications render with data (passing)
  it('renders GitHub notifications with repo and title', () => {
    const ghBrief: DailyBrief = {
      ...fullBrief,
      ghNotifications: [
        {
          id: '1',
          reason: 'mention',
          unread: true,
          title: 'Fix login bug',
          type: 'Issue',
          repo: 'owner/repo',
          repoUrl: 'https://github.com/owner/repo',
          humanUrl: 'https://github.com/owner/repo/issues/1',
          updatedAt: new Date().toISOString(),
        },
        {
          id: '2',
          reason: 'team_mention',
          unread: false,
          title: 'Add dark mode',
          type: 'PullRequest',
          repo: 'owner/other',
          repoUrl: 'https://github.com/owner/other',
          humanUrl: 'https://github.com/owner/other/pull/2',
          updatedAt: new Date().toISOString(),
        },
      ],
    };

    const result = renderToHtml(ghBrief);
    expect(result).toContain('owner/repo');
    expect(result).toContain('Fix login bug');
    expect(result).toContain('owner/other');
    expect(result).toContain('Add dark mode');
    expect(result).not.toContain('⚠ Unavailable');
  });

  // Task 1.7 — charset + viewport meta (passing)
  it('output contains charset and viewport meta tags', () => {
    const result = renderToHtml(fullBrief);
    expect(result).toContain('<meta charset="UTF-8">');
    expect(/meta name="viewport"/.test(result)).toBe(true);
  });

  // Task 1.8 — feelsLikeC null renders N/A (passing)
  it('renders N/A when feelsLikeC is null', () => {
    const briefWithNullFeels: DailyBrief = {
      ...fullBrief,
      weather: {
        ...fullBrief.weather!,
        feelsLikeC: null,
      },
    };

    const result = renderToHtml(briefWithNullFeels);
    expect(result).toContain('N/A');
    expect(result).not.toContain('null');
    expect(result).not.toContain('undefined');
  });

  // Task 1.9 — thumbnailUrl renders img (failing — renderer has gap)
  it('renders Wikipedia thumbnail img when thumbnailUrl is set', () => {
    const briefWithThumb: DailyBrief = {
      ...fullBrief,
      wikiArticle: {
        ...fullBrief.wikiArticle!,
        thumbnailUrl: 'https://upload.wikimedia.org/thumb.jpg',
      },
    };

    const result = renderToHtml(briefWithThumb);
    expect(result).toContain('<img');
    expect(result).toContain('thumb.jpg');
  });

  // Task 1.10 — thumbnailUrl null renders no img (passing after Task 2.2)
  it('does not render img when thumbnailUrl is null', () => {
    const result = renderToHtml(fullBrief);
    const wikiSectionMatch = result.match(/<div[^>]*id="wikipedia"[\s\S]*?<\/div>/);
    if (wikiSectionMatch) {
      expect(wikiSectionMatch[0]).not.toContain('wiki-thumb');
      expect(wikiSectionMatch[0]).not.toMatch(/<img[\s>]/);
    }
  });
});

export interface SectionStatus { ok: boolean; error?: string }
export interface WeatherData {
  lat: number; lon: number; tempC: number; feelsLikeC: number | null;
  humidity: number | null; description: string; windSpeedKmh: number; isDay: boolean;
}
export interface HNStory {
  id: string; title: string; url: string | null; points: number;
  commentCount: number; author: string;
}
export interface GHNotification {
  id: string; reason: string; unread: boolean; title: string; type: string;
  repo: string; repoUrl: string; humanUrl: string; updatedAt: string;
}
export interface WikiArticle {
  title: string; summary: string; url: string; thumbnailUrl: string | null;
}
export interface DailyBrief {
  generatedAt: string;
  weather: WeatherData | null;
  hnStories: HNStory[];
  ghNotifications: GHNotification[];
  wikiArticle: WikiArticle | null;
  status: {
    weather: SectionStatus; hn: SectionStatus;
    github: SectionStatus; wikipedia: SectionStatus;
  };
}
